from qiskit import QuantumCircuit
from qiskit.primitives import BasePrimitiveJob, StatevectorSampler

qc = QuantumCircuit(2)
qc.h(0); qc.cx(0, 1); qc.measure_all()
job = StatevectorSampler().run([qc], shots=64)
res = job.result()
printed = f"{isinstance(job, BasePrimitiveJob)} {type(res).__name__} {type(res[0]).__name__}"

claims = {
    "A": "True PrimitiveResult PubResult",
    "B": "False PrimitiveResult SamplerPubResult",
    "C": "True SamplerResult SamplerPubResult",
    "D": "True PrimitiveResult DataBin",
    "E": "True PrimitiveResult BitArray",
    "F": "True PrimitiveResult SamplerPubResult",
}
flags = {k: (v == printed) for k, v in claims.items()}
evidence = {
    k: f"the script printed '{printed}'; this option predicts '{v}' -> match={flags[k]}"
    for k, v in claims.items()
}
evidence["A"] += f"; the pub's class chain is {[c.__name__ for c in type(res[0]).__mro__]}, so it is a PubResult by inheritance while its own class name is not"
evidence["B"] += f"; the local job object is a {type(job).__name__} and the abstract methods it implements are {sorted(BasePrimitiveJob.__abstractmethods__)}"
evidence["D"] += f"; the data bin is one layer in: type(res[0].data).__name__ = {type(res[0].data).__name__}"
evidence["E"] += f"; the bit array is deeper still: type(res[0].data.meas).__name__ = {type(res[0].data.meas).__name__}"
emit_verdict({
    "answer": sorted(k for k, v in flags.items() if v),
    "evidence": evidence,
    "observed": {
        "printed": printed,
        "job_type": type(job).__name__,
        "interface_methods": sorted(BasePrimitiveJob.__abstractmethods__),
    },
})
